import {
    createHashRouter,
    RouterProvider,
    Navigate,
    Outlet,
} from 'react-router-dom';
import ErrorPage from './components/ErrorPage';
import './locales';
import './App.module.css';
import PageWrapper from './components/PageWrapper';
import { SetChapUrl } from './features/route-api/SetChapUrl';
import { SettingsLayout } from './features/settings/SettingsLayout';
import { GeneralSettings } from './features/settings/GeneralSettings';
import { DataPruningCard } from './features/settings/DataPruning';
import { ExperimentalSettings } from './features/settings/Experimental';
import { CssReset, CssVariables } from '@dhis2/ui';
import { Layout } from './components/layout/Layout';
import { RouteValidator } from './components/RouteValidator';
import InfoAboutReportingBugs from './features/common-features/InfoAboutReportingBugs/InfoAboutReportingBugs';
import WarnAboutIncompatibleVersion from './features/common-features/WarnAboutIncompatibleVersion/WarnAboutIncompatibleVersion';
import { DashboardPage } from './pages/DashboardPage';
import { EvaluationPage } from './pages/EvaluationPage';
import { EvaluationDetailsPage } from './pages/EvaluationDetailsPage';
import { ChapValidator } from './components/ChapValidator';
import { NewEvaluationPage } from './pages/NewEvaluationPage';
import { JobsPage } from './pages/JobsPage';
import { EvaluationComparePage } from './pages/EvaluationCompare';
import { GetStartedPage } from './pages/GetStartedPage';
import { ReadyToPredictPage } from './pages/ReadyToPredictPage';
import { ConfiguredModelDashboardPage } from './pages/ConfiguredModelDashboardPage';
import { ModelsPage } from './pages/ModelsPage';
import { NewConfiguredModelPage } from './pages/NewConfiguredModelPage';
import { SyncUrlWithGlobalShell } from './utils/syncUrlWithGlobalShell';
import { NewPredictionPage } from './pages/NewPredictionPage';
import { PredictionImportPage } from './pages/PredictionImportPage';
import { PredictionRunDetailsPage } from './pages/PredictionRunDetailsPage';
import { PredictionActivityPage } from './pages/PredictionActivityPage';
import { GuidesPage } from './pages/GuidesPage';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';

export type RouteHandle = {
    fullWidth?: boolean;
    /* whether to automatically collapse the sidebar when route is active */
    collapseSidebar?: boolean;
};

const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            refetchOnWindowFocus: false,
            retry: false,
        },
    },
});

const router = createHashRouter([
    {
        element: (
            <>
                <SyncUrlWithGlobalShell />
                <Layout />
            </>
        ),
        errorElement: <ErrorPage />,
        children: [
            {
                path: '/',
                element: <Navigate to="/dashboard" replace />,
            },
            {
                element: (
                    <RouteValidator>
                        <ChapValidator>
                            <InfoAboutReportingBugs />
                            <WarnAboutIncompatibleVersion />
                            <PageWrapper>
                                <Outlet />
                            </PageWrapper>
                        </ChapValidator>
                    </RouteValidator>
                ),
                errorElement: <ErrorPage />,
                children: [
                    {
                        path: '/dashboard',
                        element: <DashboardPage />,
                    },
                    {
                        path: '/evaluate',
                        children: [
                            {
                                index: true,
                                element: <EvaluationPage />,
                            },
                            {
                                path: 'compare',
                                handle: {
                                    fullWidth: true,
                                } satisfies RouteHandle,
                                element: <EvaluationComparePage />,
                            },
                            {
                                path: 'new',
                                element: <NewEvaluationPage />,
                                handle: {
                                    collapseSidebar: true,
                                } satisfies RouteHandle,
                            },
                            {
                                path: ':evaluationId',
                                handle: {
                                    collapseSidebar: true,
                                } satisfies RouteHandle,
                                element: <EvaluationDetailsPage />,
                            },
                        ],
                    },
                    {
                        path: '/jobs',
                        element: <JobsPage />,
                    },
                    {
                        path: '/predictions',
                        children: [
                            {
                                index: true,
                                element: <ReadyToPredictPage />,
                            },
                            {
                                path: ':predictionSetupId',
                                children: [
                                    {
                                        index: true,
                                        handle: {
                                            collapseSidebar: true,
                                        } satisfies RouteHandle,
                                        element: <ConfiguredModelDashboardPage />,
                                    },
                                    {
                                        path: 'new',
                                        handle: {
                                            collapseSidebar: true,
                                        } satisfies RouteHandle,
                                        element: <NewPredictionPage />,
                                    },
                                    {
                                        path: 'runs/:predictionId',
                                        handle: {
                                            collapseSidebar: true,
                                            fullWidth: true,
                                        } satisfies RouteHandle,
                                        element: <PredictionRunDetailsPage />,
                                    },
                                    {
                                        path: 'runs/:predictionId/import',
                                        handle: {
                                            collapseSidebar: true,
                                        } satisfies RouteHandle,
                                        element: <PredictionImportPage />,
                                    },
                                    {
                                        path: 'activity',
                                        handle: {
                                            collapseSidebar: true,
                                        } satisfies RouteHandle,
                                        element: <PredictionActivityPage />,
                                    },
                                ],
                            },
                        ],
                    },
                    {
                        path: '/models',
                        children: [
                            {
                                index: true,
                                element: <ModelsPage />,
                            },
                            {
                                path: 'new',
                                element: <NewConfiguredModelPage />,
                                handle: {
                                    collapseSidebar: true,
                                } satisfies RouteHandle,
                            },
                        ],
                    },
                ],
            },
            {
                path: '/settings',
                handle: {
                    collapseSidebar: true,
                    fullWidth: true,
                } satisfies RouteHandle,
                element: <SettingsLayout />,
                children: [
                    {
                        index: true,
                        element: <GeneralSettings />,
                    },
                    {
                        path: 'data-pruning',
                        element: <DataPruningCard />,
                    },
                    {
                        path: 'experimental',
                        element: <ExperimentalSettings />,
                    },
                ],
            },
            {
                path: '/get-started',
                handle: {
                    collapseSidebar: true,
                } satisfies RouteHandle,
                element: <GetStartedPage />,
            },
            {
                path: '/guides',
                element: <GuidesPage />,
                handle: {
                    collapseSidebar: true,
                } satisfies RouteHandle,
                children: [
                    { index: true },
                    { path: ':guideSlug' },
                ],
            },
        ],
    },
]);

const App = () => {
    return (
        <>
            <QueryClientProvider client={queryClient}>
                <CssReset />
                <CssVariables theme spacers colors elevations />
                <SetChapUrl>
                    <RouterProvider router={router} />
                </SetChapUrl>
                <ReactQueryDevtools position="bottom-right" />
            </QueryClientProvider>
        </>
    );
};

export default App;
